/** Deterministic action planner for the atlas assistant.
 *
 * The chat answer itself is generated by an LLM through `/api/chat`. This module
 * still reads the same reference data the interface shows and decides which
 * model actions a question implies (highlight, rotate, labels, quiz), so
 * the assistant can keep driving the 3D viewer. It also provides the local
 * fallback used by the validation scripts. */

import {SYSTEMS,explanation,type Atlas,type Concept,type SystemId,type View} from './anatomy';
import {resolveBoneAtlas} from './bone-atlas';
import {resolveStructureAtlas} from './structure-atlas';
import {resolveStructureFact,type StructureFact} from './structure-facts';
import type {AssistantSelection} from './llm-types';
import type {QuizTopic} from './quiz/questions';

export type {AssistantSelection} from './llm-types';

export interface AssistantContext {
  atlas: Atlas;
  selection: AssistantSelection | null;
}

export type AssistantAction =
  | {kind: 'view'; view: View; label: string}
  | {kind: 'highlight'; ids: string[]; label: string; select?: boolean}
  | {kind: 'isolate'; ids: string[]; label: string}
  | {kind: 'labels'; on: boolean; label: string}
  | {kind: 'quiz'; label: string; topic?: QuizTopic};

export interface AssistantReply {
  text: string;
  actions: AssistantAction[];
}

